def configurar_procuraduria(apps, schema_editor):
    alias = schema_editor.connection.alias
    Direccion = apps.get_model('ciudadanos', 'Direccion')
    Tramite = apps.get_model('ciudadanos', 'Tramite')
    direccion = Direccion.objects.using(alias).filter(nombre__iexact='Procuraduría Social').first()
    if direccion is None:
        direccion = Direccion.objects.using(alias).create(
            nombre='Procuraduría Social', descripcion='Estudios socioeconómicos y atención psicológica.',
        )
    for nombre, servicio in (
        ('Estudio Socioeconómico', 'socioeconomico'), ('Consulta Psicológica', 'psicologia'),
    ):
        tramite = Tramite.objects.using(alias).filter(nombre__iexact=nombre).order_by('pk').first()
        if tramite is None:
            tramite = Tramite.objects.using(alias).create(
                nombre=nombre, direccion=direccion, tiempo='Por confirmar', costo='Por confirmar',
                modalidad='En línea / Presencial',
            )
        tramite.servicio_procuraduria = servicio
        tramite.save(using=alias, update_fields=['servicio_procuraduria'])


